CREATE POLICY crew_receipts_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id='crew-receipts' AND EXISTS (SELECT 1 FROM public.project_participants p JOIN public.organizations o ON o.id=p.organization_id WHERE p.organization_id::text=(storage.foldername(name))[1] AND p.project_id::text=(storage.foldername(name))[2] AND p.invite_status='ACCEPTED' AND o.type='FC' AND public.user_in_org(auth.uid(),p.organization_id) AND public.can_see_project(p.project_id)));
CREATE POLICY crew_receipts_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='crew-receipts' AND EXISTS (SELECT 1 FROM public.project_participants p JOIN public.organizations o ON o.id=p.organization_id WHERE p.organization_id::text=(storage.foldername(name))[1] AND p.project_id::text=(storage.foldername(name))[2] AND p.invite_status='ACCEPTED' AND o.type='FC' AND public.user_in_org(auth.uid(),p.organization_id) AND public.can_see_project(p.project_id)));
CREATE POLICY crew_receipts_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id='crew-receipts' AND EXISTS (SELECT 1 FROM public.project_participants p JOIN public.organizations o ON o.id=p.organization_id WHERE p.organization_id::text=(storage.foldername(name))[1] AND p.project_id::text=(storage.foldername(name))[2] AND p.invite_status='ACCEPTED' AND o.type='FC' AND public.user_in_org(auth.uid(),p.organization_id) AND public.can_see_project(p.project_id)));
CREATE UNIQUE INDEX crew_tracker_one_worker_per_day ON public.actual_cost_entries (organization_id,project_id,tracker_worker_id,entry_date) WHERE tracker_category='labor' AND tracker_worker_id IS NOT NULL;
COMMENT ON INDEX public.crew_tracker_one_worker_per_day IS 'Prevents an accidental duplicate daily roll-call for the same worker and project; edit the existing quantity instead.';